# ── Combustion (Astangata) ───────────────────────────────────────────────────
# Arc of combustion from the Sun, in degrees. Several classical sources give a
# narrower arc for a retrograde Budha and Shukra, because a retrograde planet
# meets the Sun at inferior conjunction and is nearer the Earth. Both numbers
# are therefore kept, and the profile as a whole is replaceable — traditions
# differ, so nothing here is hard-coded into the rule engine.
#
# Rahu and Ketu are deliberately absent: they are chaya grahas (shadow points),
# not bodies that can be burnt by the Sun's rays, so they are never combust.

@dataclass(frozen=True)
class CombustionProfile:
    """Combustion arcs in degrees, by planet and direction of motion."""

    name: str
    direct: dict[str, float]
    retrograde: dict[str, float] = field(default_factory=dict)

    def orb_for(self, planet: str, is_retrograde: bool) -> Optional[float]:
        """Arc for this planet, or None if it can never be combust."""
        if is_retrograde and planet in self.retrograde:
            return self.retrograde[planet]
        return self.direct.get(planet)

    def applies_to(self, planet: str) -> bool:
        return planet in self.direct


CLASSICAL_COMBUSTION = CombustionProfile(
    name="classical",
    direct={"Chandra": 12.0, "Mangal": 17.0, "Budha": 14.0,
            "Guru": 11.0, "Shukra": 10.0, "Shani": 15.0},
    retrograde={"Budha": 12.0, "Shukra": 8.0},
)

COMBUSTION_PROFILES: dict[str, CombustionProfile] = {
    "classical": CLASSICAL_COMBUSTION,
}

DEFAULT_COMBUSTION = CLASSICAL_COMBUSTION

# Retained for callers that predate the profile object.
COMBUSTION_ORB = dict(CLASSICAL_COMBUSTION.direct)


def _deg(x: float) -> float:
    return x % 360.0


# Below this apparent daily motion the engine's own accuracy cannot resolve the
# direction of travel, so the body is reported as stationary rather than as
# direct or retrograde. See AUDIT.md for the measured speed errors this is
# derived from: it is an honesty threshold, not an astronomical definition.
STATIONARY_SPEED_THRESHOLD = 0.005


# Dignity groupings used by the interpretation engine.
STRONG_DIGNITIES = ("Parama Uchcha", "Uchcha", "Moolatrikona", "Swa")
WEAK_DIGNITIES = ("Neecha", "Parama Neecha")


# ── Data Classes ─────────────────────────────────────────────────────────────

@dataclass
class PlanetPosition:
    name: str
    longitude: float        # 0–360 sidereal
    rashi_index: int        # 0–11
    rashi: str
    rashi_lord: str
    degree_in_rashi: float  # 0–30
    nakshatra_index: int    # 0–26
    nakshatra: str
    nakshatra_lord: str
    pada: int               # 1–4
    is_retrograde: bool
    dignity: str            # Uchcha / Swa / Neecha / Moolatrikona / Neutral
    speed: float            # degrees/day
    latitude: float = 0.0
    is_combust: bool = False
    sun_separation: Optional[float] = None   # degrees, 0–180, None for the Sun
    combustion_orb: Optional[float] = None   # arc that was applied, if any

    @property
    def is_stationary(self) -> bool:
        """Within the accuracy of the elements the direction cannot be resolved."""
        return abs(self.speed) < STATIONARY_SPEED_THRESHOLD and self.name not in ("Rahu", "Ketu")

    def dms(self) -> str:
        """Degrees, minutes and seconds within the rashi."""
        total = round(self.degree_in_rashi * 3600)
        d, rem = divmod(total, 3600)
        m, s = divmod(rem, 60)
        return f"{d:02d}° {m:02d}' {s:02d}\""

    def full_position(self) -> str:
        retro = " ℞" if self.is_retrograde else ""
        return f"{self.rashi} {self.dms()}{retro} [{self.nakshatra} Pada {self.pada}]"


@dataclass
class Lagna:
    longitude: float
    rashi_index: int
    rashi: str
    rashi_lord: str
    degree_in_rashi: float
    nakshatra: str
    nakshatra_lord: str
    pada: int

    def dms(self) -> str:
        total = round(self.degree_in_rashi * 3600)
        d, rem = divmod(total, 3600)
        m, s = divmod(rem, 60)
        return f"{d:02d}° {m:02d}' {s:02d}\""


# ── Time helper ──────────────────────────────────────────────────────────────

def jde_from_datetime(dt_utc: datetime.datetime) -> float:
    """Julian Day (UT) from a UTC datetime."""
    if not hasattr(dt_utc, "utctimetuple"):
        raise ValueError("Pass a datetime object")
    hour = dt_utc.hour + dt_utc.minute / 60 + dt_utc.second / 3600
    return julian_day(dt_utc.year, dt_utc.month, dt_utc.day, hour)


def tropical_to_sidereal(tropical_lon: float, ayanamsha_deg: float) -> float:
    return _deg(tropical_lon - ayanamsha_deg)


# ── Nakshatra & dignity ──────────────────────────────────────────────────────

def get_nakshatra(sidereal_lon: float) -> tuple[int, str, str, int]:
    """Returns (index, nakshatra_name, lord, pada) for a sidereal longitude."""
    span = 360.0 / 27.0                       # 13°20'
    idx = min(int(sidereal_lon / span), 26)
    pada = min(int((sidereal_lon % span) / (span / 4)) + 1, 4)
    return idx, NAKSHATRA_NAMES[idx], NAKSHATRA_LORDS[idx], pada


def get_dignity(planet_name: str, rashi_index: int, degree_in_rashi: float) -> str:
    """Classical dignity of a graha by sign and degree."""
    if planet_name in EXALTATION:
        ex_rashi, ex_deg = EXALTATION[planet_name]
        if rashi_index == ex_rashi:
            return "Parama Uchcha" if abs(degree_in_rashi - ex_deg) < 1 else "Uchcha"
    if planet_name in DEBILITATION:
        deb_rashi, deb_deg = DEBILITATION[planet_name]
        if rashi_index == deb_rashi:
            return "Parama Neecha" if abs(degree_in_rashi - deb_deg) < 1 else "Neecha"
    if planet_name in MOOLATRIKONA:
        mt_rashi, start, end = MOOLATRIKONA[planet_name]
        if rashi_index == mt_rashi and start <= degree_in_rashi < end:
            return "Moolatrikona"
    if rashi_index in OWN_SIGN.get(planet_name, []):
        return "Swa"
    return "Neutral"


# ── Main Calculator ───────────────────────────────────────────────────────────

class JyotishChart:
    """A full sidereal chart for one birth moment and place."""

    def __init__(self, jde: float, lat: float, lon: float,
                 ayanamsha_system: str = "lahiri", true_node: bool = True,
                 combustion_profile: Optional[CombustionProfile] = None):
        """`jde` is the Julian Day in UT; ΔT is applied internally."""
        self.combustion_profile = combustion_profile or DEFAULT_COMBUSTION
        self.jd_ut = jde
        self.jde = jde                       # kept for existing callers
        self.jd_tt = jd_ut_to_tt(jde)
        self.delta_t = eph.delta_t_seconds(jde)
        self.lat = lat
        self.lon = lon
        self.ayanamsha_system = ayanamsha_system
        self.true_node = true_node
        self.ayanamsha = ayanamsha(self.jd_tt, ayanamsha_system)
        self.planets: dict[str, PlanetPosition] = {}
        self.lagna: Optional[Lagna] = None
        self.midheaven: Optional[float] = None
        self.source = "calculated"
        self._compute()

    # ── construction helpers ──────────────────────────────────────────────
    def _make_position(self, name: str, trop_lon: float, speed: float,
                       latitude: float = 0.0) -> PlanetPosition:
        sid_lon = tropical_to_sidereal(trop_lon, self.ayanamsha)
        return self._position_from_sidereal(name, sid_lon, speed, latitude)

    @staticmethod
    def _position_from_sidereal(name: str, sid_lon: float, speed: float,
                                latitude: float = 0.0) -> PlanetPosition:
        """Build a PlanetPosition from an already-sidereal longitude."""
        sid_lon = _deg(sid_lon)
        rashi_idx = int(sid_lon / 30) % 12
        deg_in_rashi = sid_lon % 30
        nak_idx, nak_name, nak_lord, pada = get_nakshatra(sid_lon)
        rashi = RASHI_NAMES[rashi_idx]

        return PlanetPosition(
            name=name,
            longitude=sid_lon,
            rashi_index=rashi_idx,
            rashi=rashi,
            rashi_lord=RASHI_LORDS[rashi],
            degree_in_rashi=deg_in_rashi,
            nakshatra_index=nak_idx,
            nakshatra=nak_name,
            nakshatra_lord=nak_lord,
            pada=pada,
            is_retrograde=speed < 0,
            dignity=get_dignity(name, rashi_idx, deg_in_rashi),
            speed=speed,
            latitude=latitude,
        )

    @staticmethod
    def _lagna_from_sidereal(sid_lon: float) -> Lagna:
        """Build a Lagna from an already-sidereal longitude."""
        sid_lon = _deg(sid_lon)
        rashi_idx = int(sid_lon / 30) % 12
        _, nak_name, nak_lord, pada = get_nakshatra(sid_lon)
        return Lagna(
            longitude=sid_lon,
            rashi_index=rashi_idx,
            rashi=RASHI_NAMES[rashi_idx],
            rashi_lord=RASHI_LORDS[RASHI_NAMES[rashi_idx]],
            degree_in_rashi=sid_lon % 30,
            nakshatra=nak_name,
            nakshatra_lord=nak_lord,
            pada=pada,
        )

    def _mark_combustion(self):
        """
        Flag grahas too close to the Sun to give their results freely, and
        record the angular separation whether or not the graha is combust —
        the rule engine needs the distance, not only the verdict.
        """
        sun = self.planets.get("Surya")
        if sun is None:
            return
        profile = self.combustion_profile
        for name, planet in self.planets.items():
            if name == "Surya":
                continue
            separation = abs((planet.longitude - sun.longitude + 180) % 360 - 180)
            planet.sun_separation = separation
            orb = profile.orb_for(name, planet.is_retrograde)
            if orb is None:                      # Rahu/Ketu are never combust
                planet.is_combust = False
                planet.combustion_orb = None
                continue
            planet.combustion_orb = orb
            planet.is_combust = separation < orb

    def _compute(self):
        jd_tt = self.jd_tt

        for name in PLANET_NAMES:
            trop = eph.tropical_longitude(name, jd_tt, self.true_node)
            speed = eph.daily_motion(name, jd_tt, self.true_node)
            latitude = (eph.planet_latitude(name, jd_tt)
                        if name in ("Mangal", "Budha", "Guru", "Shukra", "Shani")
                        else 0.0)
            self.planets[name] = self._make_position(name, trop, speed, latitude)

        self.speeds_are_measured = set(PLANET_NAMES)
        self._mark_combustion()

        trop_asc = eph.ascendant(self.jd_ut, jd_tt, self.lat, self.lon)
        self.lagna = self._lagna_from_sidereal(
            tropical_to_sidereal(trop_asc, self.ayanamsha))
        self.midheaven = tropical_to_sidereal(
            eph.midheaven(self.jd_ut, jd_tt, self.lon), self.ayanamsha)

    @classmethod
    def from_sidereal_longitudes(cls,
                                 lagna_lon: float,
                                 planet_lons: dict[str, float],
                                 retrograde: Optional[set] = None,
                                 ayanamsha: float = 0.0,
                                 jde: float = 0.0,
                                 lat: float = 0.0,
                                 lon: float = 0.0,
                                 speeds: Optional[dict[str, float]] = None,
                                 combustion_profile: Optional[CombustionProfile] = None
                                 ) -> "JyotishChart":
        """
        Build a chart directly from entered sidereal degrees, bypassing all
        ephemeris computation. These values stay authoritative and unmodified.

        `speeds` carries real daily motion across from a calculated chart where
        it is known. Bodies without a speed get a placeholder of ±1°/day, which
        preserves only the direction of travel: their `is_stationary` flag is
        meaningless and must not be read as an astronomical statement.
        """
        chart = cls.__new__(cls)
        chart.combustion_profile = combustion_profile or DEFAULT_COMBUSTION
        chart.jd_ut = jde
        chart.jde = jde
        chart.jd_tt = jde
        chart.delta_t = 0.0
        chart.lat = lat
        chart.lon = lon
        chart.ayanamsha_system = "as entered"
        chart.true_node = True
        chart.ayanamsha = ayanamsha
        chart.midheaven = None
        chart.source = "entered"
        retro = retrograde or set()
        known_speeds = speeds or {}
        chart.planets = {
            name: cls._position_from_sidereal(
                name, value,
                known_speeds.get(name, -1.0 if name in retro else 1.0))
            for name, value in planet_lons.items()
        }
        chart.speeds_are_measured = set(known_speeds)
        chart.lagna = cls._lagna_from_sidereal(lagna_lon)
        chart._mark_combustion()
        return chart

    # ── output ────────────────────────────────────────────────────────────
    def house_of(self, planet_name: str) -> int:
        """1-indexed whole-sign house of a graha, counted from Lagna."""
        planet = self.planets.get(planet_name)
        if planet is None or self.lagna is None:
            return 0
        return ((planet.rashi_index - self.lagna.rashi_index) % 12) + 1

    def print_chart(self):
        print(f"\n{'='*72}")
        print(f"  JYOTISH CHART")
        print(f"  Positions : {self.source}")
        print(f"  Ayanamsha : {self.ayanamsha_system} {self.ayanamsha:.4f}°"
              f"   |  Node: {'true' if self.true_node else 'mean'}"
              f"   |  ΔT: {self.delta_t:.1f}s")
        print(f"{'='*72}")
        print(f"\n  LAGNA: {self.lagna.rashi} {self.lagna.dms()}"
              f"   [{self.lagna.nakshatra} Pada {self.lagna.pada}]"
              f"   Lord: {self.lagna.rashi_lord}")
        if self.midheaven is not None:
            mc_sign = RASHI_NAMES[int(self.midheaven / 30) % 12]
            print(f"  MC   : {mc_sign} {self.midheaven % 30:.2f}°")

        print(f"\n{'─'*72}")
        print(f"  {'Planet':<9} {'Rashi':<11} {'Degree':<15} {'Nakshatra':<21} "
              f"{'Speed':>7}  Dignity")
        print(f"{'─'*72}")
        for name in PLANET_NAMES:
            p = self.planets.get(name)
            if p is None:
                continue
            marks = ("℞" if p.is_retrograde else " ") + ("*" if p.is_combust else "")
            if p.is_stationary:
                marks += "S"
            print(f"  {name:<9} {p.rashi:<11} {p.dms():<15} "
                  f"{p.nakshatra + ' P' + str(p.pada):<21} {p.speed:>7.3f}  "
                  f"{p.dignity} {marks}")
        print(f"{'─'*72}")
        print("  ℞ retrograde   * combust   S stationary")
        print(f"{'='*72}\n")
